import {
	ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS,
	ANGULAR_TINY_TRANSLATOR_MIGRATED_LANE_CHAIN,
	ANGULAR_TINY_TRANSLATOR_SOURCE,
