381	export const WITNESS_DOWNLOAD_CAPTURE_RULE =
382		'A browser context accepts downloads only where the application declared that it produces them. Where it did, every download the page produced is read back by suggested filename, byte length and sha256 and ledgered individually. An application that declared none runs in a context that refuses downloads, so one it never claimed to produce cannot succeed unobserved.' as const;
383	
384	/** One file-input surface an application declared, by selector and fixture. */
385	export type WitnessFileInputSurfaceEntry = {
386		label: string;
387		selector: string;
388		/**
389		 * The fixture as declared: a repository-relative path, never a host-specific
390		 * absolute one, so the evidence names the file rather than the machine.
391		 */
392		fixturePath: string;
393	};
394	
395	/** One load as it happened, recorded from the exact bytes handed to the page. */
396	export type WitnessFileInputLoadEntry = WitnessFileInputSurfaceEntry & {
397		/** The name the page's own `File` object carries. */
398		fileName: string;
399		bytes: number;
400		sha256: string;
401	};
402	
403	/**
404	 * Accounting for the file-input mechanism, held to the same non-masking
405	 * discipline as the other inventories: every declared surface is either loaded
406	 * or explicitly unused, and `outsideDeclaration` must stay empty by
407	 * construction — a load through a surface nobody declared is impossible to
408	 * reach and fails the run if it is ever recorded.
409	 */
410	export type WitnessFileInputLoadInventory = {
411		policy: 'declared-file-input-surfaces-only';
412		rule: typeof WITNESS_FILE_INPUT_LOAD_RULE;
413		declared: WitnessFileInputSurfaceEntry[];
414		loaded: WitnessFileInputLoadEntry[];
415		unused: WitnessFileInputSurfaceEntry[];
416		outsideDeclaration: [];
417	};
418	
419	/** One download as the browser wrote it, read back rather than counted. */
420	export type WitnessCapturedDownloadEntry = {
421		suggestedFilename: string;
422		bytes: number;
423		sha256: string;
424	};
425	
426	/**
427	 * Accounting for the download-capture mechanism. `acceptDownloads` records the
428	 * browser-context capability this run was granted, so a reader can see that the
429	 * capability and the evidence came from the same declaration.
430	 */
431	export type WitnessDownloadCaptureInventory = {
432		policy: 'declared-download-surface-only';
433		rule: typeof WITNESS_DOWNLOAD_CAPTURE_RULE;
434		acceptDownloads: true;
435		captured: WitnessCapturedDownloadEntry[];
436	};
437	
438	/**
