const {createHash}=require('crypto'); const fs=require('fs'); const path=require('path');
const h=(x)=>createHash('sha256').update(x).digest('hex');
// Material Icons asset set: compute raw and latin1 digests from real bytes on disk
const dir='.versionless/cache/angular-super-productivity-v2-13-15-baseline/dist-run2';
const pairs=[];
for(const f of fs.readdirSync(dir)){ if(!/Material/.test(f)) continue; const b=fs.readFileSync(path.join(dir,f)); pairs.push([f,h(b),h(b.toString('latin1'))]); }
const raws=new Set(pairs.map(p=>p[1])), lat=new Set(pairs.map(p=>p[2]));
function walk(d,acc=[]){ for(const e of fs.readdirSync(d,{withFileTypes:true})){ const p=path.join(d,e.name); if(e.isDirectory()) walk(p,acc); else if(e.name.endsWith('.json')) acc.push(p);} return acc; }
const files=walk('evidence');
const rawHits=[], latHits=[];
for(const f of files){ const t=fs.readFileSync(f,'utf8');
  if([...raws].some(x=>t.includes(x))) rawHits.push(f);
  if([...lat].some(x=>t.includes(x))) latHits.push(f);
}
console.log('Material Icons files probed:', pairs.length);
console.log();
console.log('records citing RAW (correct) digests:', rawHits.length); rawHits.forEach(f=>console.log('   ',f));
console.log();
console.log('records citing LATIN1 (defective) digests:', latHits.length); latHits.forEach(f=>console.log('   ',f));
"
